typedef float (*FilterFunc)(float data, void* ctx);

// Algorithm core
float process_data(float input, FilterFunc filter, void* context) {
    return filter(input, context);
}

// Concrete callback
float apply_gain(float v, void* ctx) {
    float gain = *(float*)ctx;
    return v * gain;
}

// Setup and Invocation
float gain_factor = 1.5f;
float reading = 100.0f;

float boosted = process_data(
    reading, apply_gain, &gain_factor
);
// boosted == 150.0f
